#!/usr/bin/env node
/* tools/build-bundle.js — concatenate everything a browser must load into engine/hosp.bundle.js (one <script> tag)
   and print the size. The bundle is the files of engine/load-order.json in order; it is generated, do not edit it. */
const fs=require('fs'),path=require('path'),zlib=require('zlib');const root=path.join(__dirname,'..');
const files=require(path.join(root,'engine','index.js')).files();let out='/* Generated by tools/build-bundle.js. Do not edit. */\n',rows=[];
const group={};files.forEach(f=>{const s=fs.readFileSync(path.join(root,f),'utf8');out+='\n/* ---- '+f+' ---- */\n'+s+'\n';const g=f.split('/').slice(0,f.startsWith('modules/')?2:1).join('/');group[g]=(group[g]||0)+Buffer.byteLength(s);});
fs.writeFileSync(path.join(root,'engine','hosp.bundle.js'),out);
Object.keys(group).forEach(g=>console.log(String(group[g]).padStart(8)+' bytes  '+g));
console.log(String(Buffer.byteLength(out)).padStart(8)+' bytes  engine/hosp.bundle.js ('+files.length+' files; '+zlib.gzipSync(out).length+' bytes gzipped)');
